insert into public.cpl_memory (slug, kind, org, title, summary, detail, plain, tags, affects, source, related, author, event_date, status, verified_by)
values
('nc-attestation-surface-built-2026-10-25', 'milestone', 'cpl', 'The noncredit attestation is live: a college attests once a fiscal year from its funding drill-in; the CO rejects (cpl-project-tracker#2433)', 'Built by S470 under Sam''s Sheets 113 and 114 (2026-10-22): cpl_funding_nc_attestation, one row per college and fiscal year, attest-first, the CO''s Reject; the _pub view publishes the coordinator''s name and title for this year and the next; the review RPC gives the CO the rest (a count of 1 to 9 masked for the team phrase). Applied 05:50Z 2026-10-25, run 40166859960.', '#2433. The view keeps this fiscal year and the next (cpl_funding_fy(), July to June), so last year''s row lapses on July 1. Policies tested on a local Postgres 16 (17 cases). No coordinator email is collected. Folded into DR-09. Guard tests/cpl_funding_nc_attestation.test.js (23). The noncredit builder (nc_exh, nc_cdcp, nc_course) can now land: an institution that has not attested reads not yet on file and its noncredit share is held.', 'Colleges can now attest to their noncredit CPL coordinator and strike team on the funding page.', array['funding','implementation-funding','noncredit','attestation','scenario-4']::text[], array['cpl_funding.js','kb/supabase_cpl_funding_nc_attestation.sql']::text[], 'S470 build, #2433 merged 05:44Z, applied 05:50Z 2026-10-25', array['sam-sheet-113-rulings-2026-10-22','sam-sheet-114-rulings-2026-10-22','pitfall-nc-pending-gate-releases-2026-10-24']::text[], 'SkyBlueCurls-S470', '2026-10-25', 'proposed', null),
('ironworker-film-pages-link-2026-10-25', 'milestone', 'cpl', 'Every publicly listed Library piece opens at a cpl-initiative.github.io address (the ironworker film moved, S470)', 'The last listed Library piece off GitHub Pages, ironworker-pathway-in-motion, moved from the film''s github.com file page to the same file on Pages through one guarded UPDATE (receipt cpl_library_ironworker_pages_url_2026-10-25_s470, run 40162123856, read back 04:32Z). Sam''s two edits of the record only listed it; the github.com url came from the seed.', '#2432. The record''s versions keep the github.com link (team view only; cpl_library_public() returns url alone).', 'All public library links now use the cplinitiative GitHub Pages address.', array['library','public-library','github-pages']::text[], array['cpl_library']::text[], 'S470, #2432 merged 2026-10-25', array['sam-public-pieces-on-github-pages-2026-10-25']::text[], 'SkyBlueCurls-S470', '2026-10-25', 'proposed', null),
('pitfall-equity-guard-coordinator-email-2026-10-25', 'pitfall', 'cpl', 'tests/cpl_funding_equity fails if the string coordinator_email appears anywhere in cpl_funding.js', 'S470: the first build of the noncredit attestation collected the coordinator''s optional email and failed tests/cpl_funding_equity''s PII guard, which forbids the string coordinator_email anywhere in cpl_funding.js. The email came out rather than the guard bending: the condition needs the name, and MAP''s directory will carry the role''s contact.', null, 'A funding-tab field named coordinator_email trips a privacy test.', array['funding','pii','tests']::text[], array['cpl_funding.js','tests/cpl_funding_equity.test.js']::text[], 'S470 local run of tests/cpl_funding_equity.test.js (92/93, then 93/93)', array[]::text[], 'SkyBlueCurls-S470', '2026-10-25', 'proposed', null),
('pitfall-migrate-receipt-commit-runs-no-ci-2026-10-25', 'pitfall', 'cpl', 'The migrate workflow''s receipt commit leaves a PR head with no test run; the follow-up commit returns kb/migrations/.apply to main''s content', 'supabase-migrate.yml commits its receipt with the workflow token, which starts no workflow, so the PR head has no test check; and any later push re-applies while .apply differs from main''s. The fix: the next commit carries the PR''s real follow-up and returns kb/migrations/.apply to main''s content, so CI runs and nothing applies twice.', 'S470 on #2436: head 2f29c186 had no check runs; the gate in supabase-migrate.yml compares .apply with main''s and skips a head commit whose message starts with Merge.', 'After a database apply, the follow-up commit resets the trigger file so tests run and nothing applies twice.', array['supabase','migrations','ci','procedure']::text[], array['.github/workflows/supabase-migrate.yml','kb/migrations/.apply']::text[], 'S470 on #2436 (head 2f29c186 had no check runs)', array[]::text[], 'SkyBlueCurls-S470', '2026-10-25', 'proposed', null)
